window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-34f45f0a11c074b8"]={"versions": [{"id": "FIG-34f45f0a11c074b8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Paketformat (Bit-/Byte-Layout) einer SOME/IP Service Discovery (SOME/IP-SD) Option. Das Diagramm spezifiziert die Binärstruktur der IPv4 Endpoint Option innerhalb des Felds <code>Options</code> einer SOME/IP-SD-Nachricht im Ethernet-/IP-basierten Kommunikationsstapel der AUTOSAR-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option umfasst drei 32-Bit-Worte (insgesamt 12 Byte):</p>\n<ul class=\"fig-list\">\n<li><strong>Length</strong> (Bit 0–15, 16 Bit): Wert <code>0x0009</code> (9 Byte, definiert die Länge der Folgedaten einschließlich des nachfolgenden Reserved-Bytes).</li>\n<li><strong>Type</strong> (Bit 16–23, 8 Bit): Optionskennung mit festem Wert <code>0x04</code> (IPv4 Endpoint Option).</li>\n<li><strong>Reserved</strong> (Bit 24–31, 8 Bit): Fester Wert <code>0x00</code>.</li>\n<li><strong>IPv4-Address</strong> (Bit 0–31 der zweiten Zeile, 32 Bit): Unicast- oder Multicast-IPv4-Adresse des Endpunkts.</li>\n<li><strong>Reserved</strong> (Bit 0–7 der dritten Zeile, 8 Bit): Fester Wert <code>0x00</code>.</li>\n<li><strong>L4-Proto</strong> (Bit 8–15 der dritten Zeile, 8 Bit): Transportprotokoll der Schicht 4 (<code>TCP/UDP...</code>, z. B. <code>0x06</code> für TCP oder <code>0x11</code> für UDP).</li>\n<li><strong>Port Number</strong> (Bit 16–31 der dritten Zeile, 16 Bit): L4-Portnummer des Endpunkts.</li>\n</ul>\n<p class=\"fig-p\">Rechts kennzeichnet ein Maßpfeil den durch das Längenfeld abgedeckten Datenbereich (<code>Covered by Length (incl. Reserved)</code>, 9 Byte ab Byte 2).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenlayout zur Serialisierung und Deserialisierung im SOME/IP-SD-Modul. Die Option wird von einem Service-Provider oder Service-Consumer innerhalb einer SOME/IP-SD-Nachricht (Entries/Options-Array) übermittelt, um IP-Adresse, Transportprotokoll und Port für Service-Instanzen oder Eventgruppen-Endpunkte bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Bit-Layout für Implementierungen von SOME/IP-SD. Die Byte-Reihenfolge ist Big-Endian (Network Byte Order). Das Längenfeld deckt exakt 9 Byte ab (Typ-Byte, Reserviert-Byte 1, 4 Byte IPv4-Adresse, Reserviert-Byte 2, 1 Byte L4-Protokoll und 2 Byte Portnummer). Reservierte Felder sind zwingend mit <code>0x00</code> zu belegen und empfängerseitig zu ignorieren bzw. gemäß Spezifikation zu behandeln.</p>"}, {"id": "FIG-ef60f6b424f22014", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll-Paketformat (Bit-/Byte-Layout) einer SOME/IP Service Discovery (SOME/IP-SD) Option. Das Diagramm spezifiziert die Binärstruktur der IPv4 SD Endpoint Option (Option-ID <code>0x24</code>) innerhalb des Felds <code>Options</code> einer SOME/IP-SD-Nachricht im Ethernet-/IP-basierten Kommunikationsstapel der AUTOSAR-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option umfasst drei 32-Bit-Worte (insgesamt 12 Byte) mit übergeordneter Formatbezeichnung <code>Option format: IPv4 SD Endpoint Option (option-id = 0x24)</code>:</p>\n<ul class=\"fig-list\">\n<li><strong>Length</strong> (Bit 0–15, 16 Bit): Wert <code>0x0009</code> (9 Byte, definiert die Länge der Folgedaten einschließlich des nachfolgenden Reserved-Bytes).</li>\n<li><strong>Type</strong> (Bit 16–23, 8 Bit): Optionskennung mit festem Wert <code>0x24</code> (IPv4 SD Endpoint Option).</li>\n<li><strong>Reserved</strong> (Bit 24–31, 8 Bit): Fester Wert <code>0x00</code>.</li>\n<li><strong>IPv4-Address</strong> (Bit 0–31 der zweiten Zeile, 32 Bit): IPv4-Adresse des SD-Endpunkts.</li>\n<li><strong>Reserved</strong> (Bit 0–7 der dritten Zeile, 8 Bit): Fester Wert <code>0x00</code>.</li>\n<li><strong>L4-Proto</strong> (Bit 8–15 der dritten Zeile, 8 Bit): Transportprotokoll der Schicht 4 (<code>UDP/...</code>).</li>\n<li><strong>Port Number</strong> (Bit 16–31 der dritten Zeile, 16 Bit): L4-Portnummer des Endpunkts.</li>\n</ul>\n<p class=\"fig-p\">Rechts kennzeichnet ein Maßpfeil den durch das Längenfeld abgedeckten Datenbereich (<code>Covered by Length (incl. Reserved)</code>, 9 Byte ab Byte 2).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenlayout zur Serialisierung und Deserialisierung im SOME/IP-SD-Modul. Die Option dient der Bekanntgabe des IPv4-Endpunkts für den Service-Discovery-Kanal selbst (SD-Endpunkt, primär UDP-basiert) innerhalb von SOME/IP-SD-Nachrichten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Bit-Layout für SOME/IP-SD-Implementierungen. Die Byte-Reihenfolge ist Big-Endian (Network Byte Order). Das Feld <code>Type</code> ist strikt auf <code>0x24</code> festgelegt, das Längenfeld deckt exakt 9 Byte ab. Reservierte Felder sind auf <code>0x00</code> zu setzen. Als L4-Protokoll ist primär UDP vorgesehen.</p>"}], "trans": []};
